    "explanation": "The apical pansystolic murmur suggests mitral regurgitation from rheumatic carditis. If a valve lesion remains after the acute illness, prophylaxis continues for 10 years or until age 40, whichever is longer. If follow-up echo shows no residual valve disease, the lecture instead uses 10 years or until age 21, so persistence of the lesion matters.",
