    "explanation": "His established cardiovascular disease may justify a higher transfusion threshold than the usual restrictive approach in an otherwise healthy patient. C is the best listed principle, but the actual hemoglobin, ongoing blood loss, symptoms, and cardiac status must determine whether transfusion is needed. Normal resting vital signs do not make this an automatically low-risk bleed.",
