    "explanation": "The presentation suggests cirrhosis with an acute upper GI bleed, so antibiotics such as ceftriaxone should be started along with resuscitation and vasoactive treatment. Octreotide is also appropriate, but its usual course is 2-5 days rather than only 24 hours. Suspected variceal bleeding needs endoscopy within about 12 hours after initial stabilization, making D the most fully correct option.",
