    "explanation": "Severe epigastric pain radiating to the back suggests acute pancreatitis. A small or normal amylase result does not exclude it, including in hypertriglyceridemia-associated disease, but diagnosis still requires a second criterion such as marked lipase elevation or imaging. The printed amylase reference range is unclear and should not be treated as diagnostic.",
