    "explanation": "Acute MI requires acute myocardial injury, usually a rise or fall in troponin with a value above the diagnostic threshold, plus evidence of ischemia. Troponin elevation with ischemic symptoms is therefore the best listed combination; troponin elevation alone can have non-coronary causes.",
