    "explanation": "Conn syndrome is primary aldosteronism and is a cause of secondary hypertension. Excess aldosterone promotes sodium and water retention and increases urinary potassium loss. Hypertension with otherwise unexplained hypokalemia is a useful clue, although potassium can also be normal.",
