    "explanation": "If acute hepatitis B is the intended diagnosis, the relevant IgM marker is IgM antibody to the HBV core antigen. It helps distinguish a recent HBV episode from a pattern of old exposure, though it may also appear during a flare of chronic infection. The gastrointestinal prodrome and ALT-predominant injury do not identify HBV by themselves, and “HBV IgM” is an imprecise test label.",
