    "explanation": "Hypocalcemia is a classic biochemical abnormality in CKD. Reduced calcitriol formation limits intestinal calcium absorption, and retained phosphate further contributes to low calcium and secondary hyperparathyroidism. CKD more often causes high potassium, low active vitamin D, and increased PTH than the opposite abnormalities listed.",
