    "explanation": "Hypocalcemia is the important expected complication after parathyroidectomy. The sudden PTH reduction decreases calcium mobilization, and previously high-turnover bone may rapidly take up calcium, producing hungry bone syndrome. The lecture describes potentially severe postoperative hypocalcemia requiring calcium and active vitamin D support.",
