    "confidence": "supported",
    "basis": "lecture",
    "explanation": "HBsAg indicates current HBV infection, and HBeAg generally signals active viral replication and greater infectivity. The combination is therefore the best listed pattern for an infectious HBV carrier. Chronic infection requires persistence of HBsAg for more than six months, and HBV DNA is needed to quantify replication because some highly replicative infections are HBeAg-negative.",
    "objection": "The two antigens alone do not prove chronicity without duration; HBeAg-negative infection can also have high HBV DNA.",
