      "title": "Abnormal Liver Enzymes With Selected Common Liver Diseases",
      "page": 12,
      "quote": "The finding of HBeAg in the serum of an HBV carrier indicates greater infectivity, a high level of viral replication",
      "relation": "teaching",
      "sourceSha256": "9849487f343fd47194cf81bb6c9d63bf00f979e695a09e1a74917b82787c929d",
