    "confidence": "preference",
    "basis": "clinical",
    "explanation": "Salbutamol can cause tachycardia, lower potassium, and aggravate arrhythmias, making it the intended cautionary choice. AF alone is not an absolute contraindication to inhaled salbutamol when it is needed for bronchospasm. Atenolol and digoxin can control AF rate, and warfarin can be indicated for stroke prevention.",
