    "confidence": "supported",
    "basis": "lecture",
    "explanation": "Ischemic chest pain with raised troponin and T-wave inversion, without diagnostic ST elevation, supports NSTEMI. Unstable angina does not produce a diagnostic troponin rise. Normal vital signs do not rule out myocardial infarction.",
