    "explanation": "Recurrent respiratory infections and infertility suggest an inherited airway-clearance disorder with bronchiectasis. Pseudomonas is a recognized pathogen in that setting and is a reasonable intended answer. Those history clues alone cannot identify the current pneumonia organism, so sputum culture is needed.",
