    "confidence": "preference",
    "basis": "clinical",
    "explanation": "Nitrofurantoin is a reasonable listed treatment for lower UTI in pregnancy when the organism is susceptible. Dysuria and pyuria without fever or flank pain fit cystitis, rather than a kidney infection for which nitrofurantoin has inadequate tissue penetration. Gestational timing, renal function, G6PD status, and urine culture guide the final choice; amoxicillin–clavulanate can also be used when appropriate.",
