    "explanation": "Progressive difficulty with both solids and liquids, with no obstructing lesion on endoscopy, favors achalasia. This is a swallowing-movement problem rather than a simple solid-food blockage. Manometry is needed to confirm it; a normal endoscopy alone does not establish the diagnosis.",
