    "confidence": "supported",
    "basis": "lecture",
    "explanation": "Screen for common causes of unexplained hepatocellular enzyme elevation, including viral hepatitis, iron overload, and autoimmune liver disease. ALT and AST are raised while ALP and GGT are normal, making a primary biliary obstruction less likely. Absence of reported viral risk does not exclude infection, and biopsy is generally reserved for an unresolved cause after the initial workup.",
