    "basis": "lecture",
    "explanation": "Start with an anti-HCV antibody test, ideally with automatic HCV RNA testing if it is reactive. An antibody shows exposure, while RNA establishes current infection. If a recent exposure or acute HCV is specifically suspected, order RNA even when antibodies are still negative; merely living with a relative who has HCV does not establish blood exposure.",
